CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','manager','cashier','inventory','accountant')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE role_permissions(role TEXT NOT NULL,permission TEXT NOT NULL,PRIMARY KEY(role,permission));
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,name_dari TEXT NOT NULL DEFAULT '',sku TEXT NOT NULL UNIQUE,category_id TEXT REFERENCES categories(id),unit TEXT NOT NULL DEFAULT 'piece',price INTEGER NOT NULL CHECK(price>=0),cost INTEGER NOT NULL CHECK(cost>=0),min_stock INTEGER NOT NULL DEFAULT 5000 CHECK(min_stock>=0),tax_bps INTEGER NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000),track_expiry INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_barcodes(code TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),multiplier INTEGER NOT NULL DEFAULT 1000 CHECK(multiplier>0));
CREATE TABLE suppliers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '');
CREATE TABLE customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',credit_limit INTEGER NOT NULL DEFAULT 0 CHECK(credit_limit>=0));
CREATE TABLE lots(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),batch TEXT NOT NULL,expires TEXT,quantity INTEGER NOT NULL CHECK(quantity>=0),cost INTEGER NOT NULL CHECK(cost>=0),received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory_movements(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),lot_id TEXT NOT NULL REFERENCES lots(id),quantity INTEGER NOT NULL CHECK(quantity<>0),reason TEXT NOT NULL,source_id TEXT,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE register_sessions(id TEXT PRIMARY KEY,opened_by TEXT NOT NULL REFERENCES users(id),opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at TEXT,opening INTEGER NOT NULL CHECK(opening>=0),counted INTEGER,expected INTEGER,notes TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX one_open_register ON register_sessions((1)) WHERE closed_at IS NULL;
CREATE TABLE cash_movements(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES register_sessions(id),amount INTEGER NOT NULL,kind TEXT NOT NULL,source_id TEXT,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,request_id TEXT NOT NULL UNIQUE,customer_id TEXT REFERENCES customers(id),cashier_id TEXT NOT NULL REFERENCES users(id),subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,cost INTEGER NOT NULL,tendered INTEGER NOT NULL,change_due INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'completed' CHECK(status='completed'),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,sku TEXT NOT NULL,unit TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,cost INTEGER NOT NULL,tax_bps INTEGER NOT NULL);
CREATE TABLE sale_allocations(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES sale_items(id),lot_id TEXT NOT NULL REFERENCES lots(id),quantity INTEGER NOT NULL CHECK(quantity>0),cost INTEGER NOT NULL);
CREATE TABLE payments(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),method TEXT NOT NULL CHECK(method IN('cash','other')),amount INTEGER NOT NULL CHECK(amount>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_ledger(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),sale_id TEXT REFERENCES sales(id),amount INTEGER NOT NULL CHECK(amount<>0),kind TEXT NOT NULL,source_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE supplier_ledger(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),amount INTEGER NOT NULL CHECK(amount<>0),kind TEXT NOT NULL,source_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchases(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,supplier_id TEXT NOT NULL REFERENCES suppliers(id),status TEXT NOT NULL DEFAULT 'ordered' CHECK(status IN('ordered','partial','received')),invoice TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchase_items(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),received INTEGER NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity),cost INTEGER NOT NULL CHECK(cost>=0));
CREATE TABLE purchase_receipts(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),item_id TEXT NOT NULL REFERENCES purchase_items(id),lot_id TEXT NOT NULL REFERENCES lots(id),quantity INTEGER NOT NULL CHECK(quantity>0),total INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE supplier_returns(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id),receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),lot_id TEXT NOT NULL REFERENCES lots(id),quantity INTEGER NOT NULL CHECK(quantity>0),amount INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE returns(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),item_id TEXT NOT NULL REFERENCES sale_items(id),quantity INTEGER NOT NULL CHECK(quantity>0),amount INTEGER NOT NULL,net_amount INTEGER NOT NULL,cost_reversed INTEGER NOT NULL,debt_offset INTEGER NOT NULL,cash_refund INTEGER NOT NULL,restock INTEGER NOT NULL,reason TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE return_allocations(return_id TEXT NOT NULL REFERENCES returns(id),allocation_id TEXT NOT NULL REFERENCES sale_allocations(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(return_id,allocation_id));
CREATE TABLE expenses(id TEXT PRIMARY KEY,category TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL CHECK(method IN('cash','other')),actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE held_carts(id TEXT PRIMARY KEY,name TEXT NOT NULL,payload TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE requests(id TEXT PRIMARY KEY,action TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE media(id TEXT PRIMARY KEY,mime TEXT NOT NULL,data BLOB NOT NULL);
CREATE INDEX lots_product ON lots(product_id,expires,received_at);
CREATE INDEX movements_product ON inventory_movements(product_id,created_at);
CREATE INDEX sales_date ON sales(created_at);
CREATE INDEX items_sale ON sale_items(sale_id);
CREATE INDEX customer_balance ON customer_ledger(customer_id,sale_id);
CREATE INDEX supplier_balance ON supplier_ledger(supplier_id);
CREATE INDEX returns_item ON returns(item_id);
INSERT INTO schema_migrations(version) VALUES(1);
